import{_ as t}from"./chunks/f5d628f74eba71b1359f.B3btxn6o.js";import{_ as o,o as a,c as i,a5 as n}from"./chunks/framework.DNkHA0lr.js";const m=JSON.parse('{"title":"Why You Always Feel Overwhelmed","description":"","frontmatter":{"title":"Why You Always Feel Overwhelmed","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/why-you-always-feel-overwhelmed.md","filePath":"en/letters/why-you-always-feel-overwhelmed.md"}'),r={name:"en/letters/why-you-always-feel-overwhelmed.md"};function s(l,e,h,u,p,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="why-you-always-feel-overwhelmed" tabindex="-1">Why You Always Feel Overwhelmed <a class="header-anchor" href="#why-you-always-feel-overwhelmed" aria-label="Permalink to &quot;Why You Always Feel Overwhelmed&quot;">​</a></h1><p>Dan Koe · 2022-08-20 · <a href="https://thedankoe.com/letters/why-you-always-feel-overwhelmed/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/why-you-always-feel-overwhelmed">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/yK4frWWTyqs?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>I’ve noticed <strong>one pattern</strong> in every:</p><ul><li>Successful entrepreneur</li><li>Enlightened spiritual guru</li><li>Happy married couple</li><li>Record breaking athlete</li></ul><p>What pattern?</p><p><strong>Focus.</strong></p><p>I’ve heard one person — from each category above — mention that “focus” is the key to their success, happiness, and progress.</p><p>After burning through books on performance, happiness, business, spirituality, philosophy, and anything else related to life enjoyment… I think I’ve found the answer.</p><p>The key to maximum life enjoyment that is (with a byproduct of success in any of your endeavors.)</p><blockquote><p>A person can make himself happy, or miserable, regardless of what is actually happening “outside,” just by changing the contents of consciousness. — Mihaly Csikszentmihaly</p></blockquote><p><em>Focus</em> is controlled consciousness.</p><p>Or, focus is controlling the “contents of consciousness.”</p><p>When the contents of your consciousness, the things you are focused on, can be made sense of in a positive manner; your life becomes positive.</p><p>Meaning, if you strive for clear, unbiased perception from an advantageous perspective of any given situation, you will feel incredible.</p><p>This also brings up a point made by Leo from Actualized.org about how <em>everything</em> is a figment of consciousness. Example: an atom is a figment of consciousness. It is a label we created to make sense of something when we became conscious of it. That is a tad more metaphysical, but it’s interesting to make the connection.</p><p>By maintaining focus on individual “figments of consciousness” — instead of split between 10 figments — we can lead happy, healthy, and fulfilling lives.</p><h2 id="content-of-consciousness" tabindex="-1">Content Of Consciousness <a class="header-anchor" href="#content-of-consciousness" aria-label="Permalink to &quot;Content Of Consciousness&quot;">​</a></h2><p>I want you to think of your mind as a supercomputer.</p><p>Your ability to process information is dependent on a few things, but I want to bring attention to your RAM.</p><p>RAM — or “random access memory” — is one of the most important parts of a computer, it determines performance.</p><p>The more RAM you use up with different programs running, open browser tabs, and the performance requirements of what you have running, the slower your performance will be.</p><p>This is no different from your focus, what you hold in your conscious attention.</p><p><a href="https://open.spotify.com/embed/episode/7EYNhtS8V9nKf5nFu7Dg2v?si=b879bc78f56c4965&amp;utm_source=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>Humans can process 126 bits of information per second. That adds up to 185 billion bits of information in your lifetime.</p><p>Most people live with multiple high-demand programs running that are draining the limited creative energy they have.</p><ul><li>Thoughts about regretful past mistakes</li><li>Thoughts about stressful future happenings</li><li>Desires of hunger and entertainment to escape those thoughts</li><li>An internal cry to break out of their conditioned way of living</li><li>A list of mixed-priority tasks that need to be finished</li><li>Open loops of tasks they were supposed to complete but forgot about</li></ul><p>The list goes on and on.</p><p>The modern mind has it’s attention split in infinite directions by default. We go about our lives stressed and near sickness. Rather than living in the present with singular focus and a worry free mind, we are the opposite. Living in a false reality created by split attention.</p><p>When we hold too much of the past or future in the contents of our consciousness, chaos ensues. The mind tends toward disorder. If not kept in check, we lose the sense of control over our lives that leads to enjoyment. This is accomplished through controlled consciousness.</p><p>AKA, Focus.</p><h2 id="_8-steps-to-reclaiming-your-focus" tabindex="-1">8 Steps To Reclaiming Your Focus <a class="header-anchor" href="#_8-steps-to-reclaiming-your-focus" aria-label="Permalink to &quot;8 Steps To Reclaiming Your Focus&quot;">​</a></h2><p>To break out of our robotic ways of living, we must first become aware of how it is impacting our life.</p><p>From chaos to order, we must bring out attention back to center and choose what deserves our attention.</p><p>The less RAM we use — the more singular our focus — the more enjoyable life becomes. Order returns and the sense of control over our lives results in a deep satisfaction with life itself.</p><p><img src="'+t+'" alt=""></p><h3 id="_1-choose-a-lagging-area-in-your-life" tabindex="-1">1) Choose A Lagging Area In Your Life <a class="header-anchor" href="#_1-choose-a-lagging-area-in-your-life" aria-label="Permalink to &quot;1) Choose A Lagging Area In Your Life&quot;">​</a></h3><p>We are only as strong as our weakest link. The areas that are lagging the furthest behind hold the lowest hanging fruit. These are the areas that cause the most problems.</p><p>Think, what area of my life is consistently causing problems that if they were solved, your quality of life would shoot through the roof.</p><p>Money? Dating? Mental health? Self-esteem? Social life? Health and energy levels? Take a walk, contemplate, and choose the one that, when fixed, the results would ripple through other areas of your life.</p><p>For the sake of this post, and a common problem for many, let’s talk about <em><strong>money</strong></em> as a lagging area.</p><h3 id="_2-gain-clarity-on-the-fundamentals" tabindex="-1">2) Gain Clarity On The Fundamentals <a class="header-anchor" href="#_2-gain-clarity-on-the-fundamentals" aria-label="Permalink to &quot;2) Gain Clarity On The Fundamentals&quot;">​</a></h3><p>I want to make a distinction between:</p><ul><li>Basics, principles, or fundamentals</li><li>Tactics, hacks, and technical details.</li></ul><p>Fundamentals drive results. Technical details can further results, but only once the fundamentals are mastered, systemized, and habitual.</p><p>Fundamentals move levers. Technical details present the opportunity for traps, overwhelm, and creating problems that don’t exist.</p><p>For our focus area of money, you need traffic and an offer. This is a universal principle for getting what you want.</p><p>If you don’t have traffic:</p><ul><li>A social media audience</li><li>Paid ads or promotions</li><li>A community or group</li><li>Organic search results</li><li>Direct outreach (i.e. cold email)</li></ul><p>Nobody will see your offer.</p><p>If you don’t have a compelling offer:</p><ul><li>Digital or physical product</li><li>Freelance or consulting service</li><li>Cohort based course or online tutoring</li><li>Membership offer or community</li></ul><p>You won’t have anywhere to send traffic to.</p><p>Like if you are in the dating market.</p><p>If you are a high-value “offer” but don’t put yourself in “traffic” heavy environments, good luck.</p><h3 id="_3-create-an-ability-based-goal" tabindex="-1">3) Create An Ability-Based Goal <a class="header-anchor" href="#_3-create-an-ability-based-goal" aria-label="Permalink to &quot;3) Create An Ability-Based Goal&quot;">​</a></h3><p>There is nothing wrong with focusing on looking better, gaining more followers, getting the most engagement, having the hottest partner, etc. Those have their use cases and can be beneficial. I would recommend paying mind to these, but not making them your primary focus.</p><p><strong>The problem:</strong> vanity-based goals are much more out of our control than ability-based goals.</p><p>These steps are not linear, it will be difficult to create an ability-based goal unless you are educated on the lever-moving actions you can take on a daily basis.</p><p>In our case, if I want to build an audience (traffic) and sell a digital product (offer) to make money — you will need to execute on levers such as:</p><ul><li>Writing 3 short-form posts a day (like tweets)</li><li>Writing 1 long-form post a week (newsletter / blog)</li><li>Condensing that long post into a medium form post (like a thread of LinkedIn post)</li><li>Spending 30-60 minutes writing out a curriculum for your digital product</li></ul><p>In this case, you could make it a goal to write 1000 high-quality words a day, and gauge yourself on the writing (instead of the results that come from it.</p><p>Process over outcome.</p><p>Speaking of writing, this is everything we go over in <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">The 2 Hour Writer.</a></p><h3 id="_4-self-educate-after-you-start" tabindex="-1">4) Self-Educate After You Start <a class="header-anchor" href="#_4-self-educate-after-you-start" aria-label="Permalink to &quot;4) Self-Educate After You Start&quot;">​</a></h3><p>The fundamentals will get you started, but you need to learn how to apply those fundamentals to your specific situation.</p><p>Too many people get trapped in “tutorial hell,” try to soak in as much information as possible, and never start.</p><p>Instead:</p><ul><li>Start and fail fast</li><li>Identify what caused you to fail</li><li>Find specific information to overcome it</li><li>Fail again and let experience compound with time</li></ul><p>Stop trying to figure everything out before you start. That’s called mental masturbation.</p><h3 id="_5-block-out-30-60-minutes-a-day" tabindex="-1">5) Block Out 30-60 Minutes A Day <a class="header-anchor" href="#_5-block-out-30-60-minutes-a-day" aria-label="Permalink to &quot;5) Block Out 30-60 Minutes A Day&quot;">​</a></h3><p>Deep work doesn’t only apply to work. It applies to every area of your life.</p><p>When entrepreneurs want to make progress in business, they dedicate time and energy to make that progress.</p><p>When married couples want to make progress in their relationships, they dedicate time for each other.</p><p>When individuals want to make progress with their mind, they dedicate time to solitude and consciousness work — like meditation.</p><p><em>Distraction-free time must be made so that your attention isn’t split when it is time to engage in “deep work,” no matter the domain of life.</em></p><h3 id="_6-immerse-yourself-in-the-content-of-that-goal" tabindex="-1">6) Immerse Yourself In The Content Of That Goal <a class="header-anchor" href="#_6-immerse-yourself-in-the-content-of-that-goal" aria-label="Permalink to &quot;6) Immerse Yourself In The Content Of That Goal&quot;">​</a></h3><p>For the spiritually inclined, this is “presence.”</p><p>For others, this is known as being “engaged” and tapped into a degree of the flow state.</p><p>Think of how you give your full attention to your phone when you are scrolling social media. Marketers and tech companies have entire teams dedicated to triggering a pseudo-flow state through attention capture.</p><p>When you get sucked into your phone, there is nothing else held in your attention. Most use this to escape reality rather than tapping into reality itself.</p><p>If your goal is related to relationships, practice filling your attention with the entirety of the other person. Their body, movements, words. Use all of your senses to feel into the moment and make that the forefront of your consciousness.</p><h3 id="_7-a-moment-of-recognition" tabindex="-1">7) A Moment Of Recognition <a class="header-anchor" href="#_7-a-moment-of-recognition" aria-label="Permalink to &quot;7) A Moment Of Recognition&quot;">​</a></h3><p>None of this comes easy. You will fail. That’s just how things are.</p><p>A distraction will register in your awareness, your attention will split, and you may get sucked into a negative feeling that the distraction triggered.</p><p>All it takes is a moment of recognition to snap yourself out of it.</p><p>Whether it be complaining through a grueling workout or being scared to approach someone new because of the identity you’ve created for that person before you’ve even talked to them.</p><p>Pause, recognize that you are resisting reality, and let it flow.</p><p>Your expectation of reality is not reality.</p><p>It’s not “supposed” to be how you <em>think</em> it should be.</p><p><em>It’s supposed to be what it’s being.</em></p><h3 id="_8-put-in-the-metaphorical-reps" tabindex="-1">8) Put In The Metaphorical Reps <a class="header-anchor" href="#_8-put-in-the-metaphorical-reps" aria-label="Permalink to &quot;8) Put In The Metaphorical Reps&quot;">​</a></h3><p>Everything is a muscle.</p><p>Your focus, relationships, business, fitness, spiritual practice, and habits of any kind. They grow with focus, ample energy to fuel performance and recovery, and direct experience so you can double down on what works for <em>you</em>_._</p><p>Do not expect quick results. Even with steroids (like courses, coaching, methods and systems) you still have to put in the reps. You can’t inject some test, sit on the couch, and expect to be the next Ronnie Coleman.</p><p>Treat every area of your life as a science project.</p><ul><li>Identify a problem</li><li>Set a desired outcome</li><li>Test different solutions</li><li>Find one that works</li><li>Replicate the results</li></ul><p>From there, continue building the muscle toward your desired outcome. Then, you will be experienced enough to know whether you want to bulk, cut, or maintain.</p><p>— Dan Koe</p><p><strong>What Happened This Week</strong></p><p>My new course, <em>The 2 Hour Writer</em>, is off to a great presale. It launches on the 27th and we have 150+ students waiting for the curriculum to drop.</p><p>If you want to learn a skill that will enhance your content, sales, perceived value, and any other marketable skillset you have, <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">check it out here.</a></p><p>A new YouTube video went live on my 3 part framework for effortless productivity.</p><p><a href="https://youtu.be/qdXFeyzq7HE" target="_blank" rel="noreferrer">Watch it here.</a></p><p>We are having a diet and lifestyle workshop inside Modern Mastery next week. Our goal is to help everyone create their own system for their health goals, whether it be building muscle, dropping fat, enhancing your energy for work, or just looking good (in a sustainable manner).</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">Koe Letter readers can join for $5.</a></p>',106)])])}const y=o(r,[["render",s]]);export{m as __pageData,y as default};
